            migrationBuilder.UpdateData(
                table: "FAQs",
                keyColumn: "Id",
                keyValue: 1L,
                columns: new[] { "Content", "ContentEn" },
                values: new object[] { "<p>Bir anı sayfası, kaybettiğiniz can dostunuzu sevgiyle hatırlamanın ve hatırasını onurlandırmanın dijital yoludur.</p><p>Fotoğraflar, videolar ve kalbinizden dökülen cümlelerle o güzel ruhun hikâyesini sonsuza dek yaşatmanıza imkan tanır.</p><p><strong>Styever anı sayfaları</strong>, sadece bir dijital günlük değil, aynı zamanda dostunuz adına yakılan her mumla sahipsiz hayvanların yaşam koşullarına katkı sağladığınız yaşayan bir sevgi defteridir.</p><p>Bu sayede dostunuzun hatırasını yaşatırken, dünyada somut bir iyilik izi bırakabilirsiniz.</p>", "<p>A memorial page is a digital way to lovingly remember and honor the companion you have lost.</p><p>It allows you to keep the story of that beautiful soul alive forever through photos, videos, and words that come from your heart.</p><p><strong>Styever memorial pages</strong> are not simply digital journals; they are living books of love where every candle lit in your companion’s memory also contributes to improving the lives of stray animals.</p><p>In this way, while keeping your companion’s memory alive, you can also leave a meaningful mark of kindness in the world.</p>" });

            migrationBuilder.UpdateData(
                table: "FAQs",
                keyColumn: "Id",
                keyValue: 12L,
                columns: new[] { "Content", "ContentEn", "Header", "HeaderEn" },
                values: new object[] { "<p>Styever’a üye olduğunuzda, platformun desteklediği projeler veya kuruluşlar arasından dilediğinizi seçebilirsiniz.</p><p>Seçtiğiniz bu projeye, ödediğiniz abonelik ücretinin net tutarı üzerinden <strong>%20 sosyal sorumluluk payı</strong> sizin adınıza tanımlanır ve ilgili kuruma iletilir.</p><p>Dostunuzun anı sayfasında her dijital mum yakıldığında, bu işlem bedelinin <strong>%80’i</strong> yine seçtiğiniz projeye veya ilgili kuruluşa ulaştırılır.</p><ul><li>Adınıza sosyal sorumluluk sertifikası oluşturulur.</li><li>Sertifika e-posta yoluyla size ulaştırılır.</li><li>Destekler ilgili proje veya kuruluşa şeffaf biçimde aktarılır.</li></ul><p>Styever, bu süreçte elde edilen toplam gelirin bir kısmını platformun devamlılığını sağlamak, anı sayfalarını güvenli bir şekilde barındırmak ve teknik altyapıyı sürdürebilmek amacıyla kullanır.</p><p>Böylece hem sahipsiz dostlarımıza sağlanan destekler şeffaf bir biçimde yerine ulaşır hem de sevdiklerinizin hatıralarını yaşatan bu dijital alan kesintisiz bir şekilde varlığını sürdürür.</p>", "<p>When you become a member of Styever, you may choose any of the projects or organizations supported by the platform.</p><p>For the project you select, <strong>20% of the net amount</strong> of your subscription payment is allocated as a social responsibility contribution on your behalf and transferred to the relevant organization.</p><p>Each time a digital candle is lit on your companion’s memorial page, <strong>80% of the transaction amount</strong> is also directed to the project or organization you selected.</p><ul><li>A social responsibility certificate is issued in your name.</li><li>The certificate is delivered to you via email.</li><li>Support is transferred transparently to the relevant project or organization.</li></ul><p>Styever uses a portion of the total revenue generated during this process to ensure the continuity of the platform, securely host memorial pages, and maintain the technical infrastructure.</p><p>In this way, support provided to stray companions is delivered transparently, while this digital space that keeps your loved ones’ memories alive continues to exist without interruption.</p>", "Sosyal sorumluluk süreci nasıl işliyor?", "How Does the Social Responsibility Process Work?" });

            migrationBuilder.InsertData(
                table: "FAQs",
                columns: new[] { "Id", "Content", "ContentEn", "Header", "HeaderEn", "IsDeleted" },
                values: new object[] { 13L, "<p>Styever olarak, kaybettiklerimizi sevgiyle anarken bugün yaşayan dostlarımızı korumayı bir görev kabul ediyoruz.</p><p>Platformumuzda gerçekleştirilen her <strong>“Mum Yakma”</strong> işlemi, yalnızca dijital bir anma ritüeli değil, aynı zamanda sahipsiz hayvanların yaşam koşullarını iyileştiren somut bir destek fırsatıdır.</p><p><strong>Süreç Nasıl İşler?</strong></p><p>Ziyaretçiler, kaybettikleri dostlarının anısına dijital bir mum yakarak onları sevgiyle anabilir ve hatıralarını tazeleyebilir.</p><p>Bu işlem sırasında elde edilen dijital hizmet gelirinin büyük bir kısmı, sosyal sorumluluk vizyonumuz kapsamında sahipsiz hayvanların mama, barınma ve tedavi ihtiyaçlarını karşılayan kuruluşlara ve projelere kaynak olarak ulaştırılır.</p><p><strong>Amacımız</strong></p><p>Dijital anıları toplumsal bir faydaya dönüştürerek sürdürülebilir bir dayanışma modeli oluşturmaktır.</p><ul><li>Her bir ışık, bir anıyı onurlandırır.</li><li>Her dijital mum, bir canın hayatında fark yaratan gerçek bir desteğe vesile olur.</li><li>Her paylaşılan anı, iyiliğe dönüşen bir bağ kurar.</li></ul><p>Biz, hatırlamanın iyileştirdiğine ve paylaşılan her anının bir başka cana nefes olabileceğine inanıyoruz.</p><p>Styever; bir dijital anma deneyimi sunarken, kullanıcılarını hayvan refahını destekleyen sosyal sorumluluk projelerinin bir parçası haline getirerek, sevgiyi ve hatıraları yaşayan bir iyilik hareketine dönüştürür.</p>", "<p>As Styever, while remembering those we have lost with love, we also consider protecting the companions who are still with us today as an important responsibility.</p><p>Every <strong>“Light a Candle”</strong> interaction on our platform is not only a digital memorial ritual, but also a meaningful opportunity to support and improve the living conditions of stray animals.</p><p><strong>How Does the Process Work?</strong></p><p>Visitors can light a digital candle in memory of their beloved companions, honoring them with love and keeping their memories alive.</p><p>A significant portion of the digital service revenue generated through this interaction is allocated, within the scope of our social responsibility vision, to organizations and projects that support the food, shelter, and medical treatment needs of stray animals.</p><p><strong>Our Purpose</strong></p><p>Our goal is to create a sustainable model of solidarity by transforming digital memories into social benefit.</p><ul><li>Every light honors a cherished memory.</li><li>Every digital candle becomes real support that makes a difference in the life of an animal in need.</li><li>Every shared memory creates a bond that turns into kindness.</li></ul><p>We believe that remembering has the power to heal, and that every shared memory can become a source of hope for another living soul.</p><p>While offering a digital memorial experience, Styever transforms love and memories into a living movement of kindness by making its users part of social responsibility projects that support animal welfare.</p>", "Anıları İyiliğe Dönüştürün", "Transform Memories into Kindness", false });
        }
